-- FLL-GAR-2023 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-05).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005173200_fll_gar_followup_hints.sql
-- Rollback: scripts/migrations/rollback-20261005173200_fll_gar_followup_hints.sql
BEGIN;
UPDATE fields x SET description = 'Ergebnis der baurechtlichen Prüfung: Ist für Herstellung, Inbetriebnahme, Nutzung und Instandhaltung des Gewässers eine Genehmigung nach Landesbauordnung erforderlich? Zu prüfen sind u. a. Bauordnung und Abgrabungsgesetze, Genehmigungsverfahren der Länder und Kommunen je nach Größe und Nutzung, Nachbarrecht, Natur-/Umweltschutzrecht, Tierschutz, Hygiene (§ 4.2; § 4.1 „baurechtliche Genehmigungen gemäß LBO“). Tor REQ-02 verlangt eine Antwort — Ja oder Nein, beides besteht; nur ein leeres Feld sperrt.
[EN] Result of the building-law check: does construction, commissioning, use and maintenance of the water body need a permit under the state building code (LBO)? Check e.g. building code and excavation acts, approval procedures of states and municipalities depending on size and use, neighbour law, nature/environmental law, animal welfare, hygiene (§ 4.2; § 4.1 ''building permits per LBO''). Gate REQ-02 demands an answer — yes or no both pass; only an empty field blocks.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.symbol = 'lbo_genehmigung_erforderlich';
UPDATE fields x SET description = 'Ergebnis der wasserrechtlichen Prüfung: Ist für die Einleitung von Überschusswasser in natürliche Gewässer, in das angrenzende Gelände oder in das öffentliche Kanalnetz eine Genehmigung nach WHG erforderlich bzw. erteilt? Die Richtlinien nennen die Einleitung „gemäß WHG“ (§ 4.1) und weisen darauf hin, dass Einleitungen genehmigungspflichtig sein können (§ 4.10). Tor REQ-03 verlangt eine Antwort — Ja oder Nein, beides besteht; nur ein leeres Feld sperrt.
[EN] Result of the water-law check: does the discharge of surplus water into natural waters, adjacent ground or the public sewer require or hold a permit under the Federal Water Act (WHG)? The guideline names discharge ''per WHG'' (§ 4.1) and notes that discharges can be subject to approval (§ 4.10). Gate REQ-03 demands an answer — yes or no both pass; only an empty field blocks.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.symbol = 'whg_einleitung_genehmigung';
UPDATE compliance_requirements x SET description = 'Besteht, sobald „LBO-Genehmigung erforderlich“ beantwortet ist – Ja oder Nein; das Tor prüft, dass die bauaufsichtliche Frage geklärt wurde, nicht, dass eine Genehmigung vorliegt. Die Richtlinien verlangen, im Planungsverlauf zu prüfen, welche bauaufsichtlichen Anforderungen Herstellung, Inbetriebnahme, Nutzung und Instandhaltung des Gewässers bestimmen (§ 4.2; § 4.1 „baurechtliche Genehmigungen gemäß LBO“). Sperrtor: Feld belegen, sonst keine Freigabe. Bei Ja die Genehmigung beantragen und in den Unterlagen nachweisen.
[EN] Passes as soon as "LBO permit required" is answered – yes or no; the gate checks that the building-law question has been settled, not that a permit exists. The guideline requires clarifying during design which building-supervision requirements govern construction, commissioning, use and maintenance of the water body (§ 4.2; § 4.1 "building permits per LBO"). Blocking gate: fill the field, otherwise no approval. If yes, apply for the permit and document it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Besteht, sobald „WHG-Einleitungsgenehmigung“ beantwortet ist – Ja oder Nein; das Tor prüft, dass die wasserrechtliche Frage für das Überschusswasser geklärt wurde. Grundlage: Einleitung in natürliche Gewässer gemäß WHG (§ 4.1); Einleitung in das angrenzende Gelände oder das öffentliche Kanalnetz kann genehmigungspflichtig sein (§ 4.10). Sperrtor: Feld belegen, sonst keine Freigabe. Bei Ja die Genehmigung einholen und nachweisen.
[EN] Passes as soon as "WHG discharge permit" is answered – yes or no; the gate checks that the water-law question for the surplus water has been settled. Basis: discharge into natural waters per WHG (§ 4.1); discharge into adjacent ground or the public sewer can be subject to approval (§ 4.10). Blocking gate: fill the field, otherwise no approval. If yes, obtain the permit and document it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-03' AND x.code = 'REQ-03';
COMMIT;
